  ddsi_typeid_copy (&key.src_type_id, &type->xt.id);
  ddsi_xt_type_fini (gv, &type->xt, true);

  struct ddsi_type_dep *dep;
  while ((dep = ddsrt_avl_lookup_succ_eq (&ddsi_typedeps_treedef, &gv->typedeps, &key)) != NULL && !ddsi_typeid_compare (&dep->src_type_id, &key.src_type_id))
  {
    ...
    if (dep->from_type_info)
    {
      struct ddsi_type *dep_type = ddsi_type_lookup_locked (gv, &dep->dep_type_id);
      ddsi_type_unref_locked (gv, dep_type);
    }
    ...
  }
  ...
}
```

So when a type is finalized, `ddsi_xt_type_fini` unrefs all member types, and then the deps are processed. If `dep->from_type_info` is set, the dep type is looked up and unref'd.

Now here's the potential UAF scenario. Consider two types A and B where:
- A is a structure with a member of type B.
- When A is created via `ddsi_type_ref_proxy`, `type_add_deps` is called which registers deps with `from_type_info=true`. This refs B (refc of B incremented).
